def candy_distribution_ways(n,k):
    mod=1000000007;dp=[0]*(k+1);dp[0]=1
    for candies in range(1,n+1):
        following=[0]*(k+1)
        for bags in range(1,min(candies,k)+1):
            following[bags]=(dp[bags-1]+bags*dp[bags])%mod
        dp=following
    return dp[k]

